#include "console.h"
#include "riscplay_audio.h"
#include "assets.h"

// Mude SPEED ou a cor abaixo. O jogo recompila automaticamente.
#define SPEED 2
#define BACKGROUND 0x0C

int main(void) {
    int x = 152, y = 82;
    unsigned frame = 0;
    const unsigned buffers[2] = {0xA080, 0x18180};
    riscplay_audio_init();
    load_pallet_from_sdram(HERO_PALETTE_ADDR);
    copy_sprite_from_sdram_to_buffer(HERO_ADDR, HERO_WIDTH * HERO_HEIGHT, 0);
    for (;;) {
        unsigned buttons = get_ps2_controller_state();
        if (BUTTON_LEFT_PRESSED(buttons)) x -= SPEED;
        if (BUTTON_RIGHT_PRESSED(buttons)) x += SPEED;
        if (BUTTON_UP_PRESSED(buttons)) y -= SPEED;
        if (BUTTON_DOWN_PRESSED(buttons)) y += SPEED;
        if (x < 0) x = 0;
        if (x > 304) x = 304;
        if (y < 0) y = 0;
        if (y > 164) y = 164;
        if (BUTTON_X_PRESSED(buttons)) riscplay_audio_note_on(0, 440);
        else riscplay_audio_note_off(0);
        set_backgound(buffers[frame & 1], BACKGROUND);
        render_sprite(1, buffers[frame & 1], HERO_WIDTH, HERO_HEIGHT, x, y, 0, 0);
        ppu_finished_all_operations();
        set_frame_buffer(buffers[frame & 1], 0);
        frame++;
    }
}

